import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
import os

# --- 1. LOAD DATA ---
# Ensure this matches the CSV generated by your FSWAP scoring run
output_csv = "fswap_qaoa_benchmark_results.csv" 

if not os.path.exists(output_csv):
    print(f"Error: {output_csv} not found. Make sure to run the scoring script first.")
    exit()

# Read the CSV directly
df = pd.read_csv(output_csv)

# Ensure data types are correct for plotting
df['n_qubits'] = pd.to_numeric(df['n_qubits'])
df['score'] = pd.to_numeric(df['score'])

# Sort for consistent legend ordering
df = df.sort_values(['n_qubits'])
qubit_counts = sorted(df['n_qubits'].unique())

# Define your preferred fixed order
backend_order = ["ibm_fez", "ibm_marrakesh", "ibm_torino"]

# --- PLOT 1: LINE PERFORMANCE TRENDS ---
sns.set_theme(style="whitegrid")
fig1, ax1 = plt.subplots(figsize=(8, 6))

sns.lineplot(
    data=df, 
    x='n_qubits', 
    y='score', 
    hue='backend', 
    hue_order=backend_order, # Ensures color consistency
    marker='o', 
    ax=ax1,
    linewidth=2.5,
    markersize=8
)

ax1.set_title('SupermarQ FSWAP QAOA', fontsize=16, fontweight='bold')
ax1.set_xlabel("Number of Qubits", fontsize=12)
ax1.set_ylabel("Score", fontsize=12)
ax1.set_ylim(-0.05, 1.05)
ax1.legend(title="IBM Backend", frameon=True)

plt.tight_layout()
plt.savefig("fswap_performance_line.png", dpi=300)
print("Saved: fswap_performance_line.png")

# --- PLOT 2: BAR CHART COMPARISON ---
sns.set_theme(style="white") 
fig2, ax2 = plt.subplots(figsize=(10, 6))

# Define palette based on number of unique qubit counts
custom_palette = sns.color_palette("tab10", len(qubit_counts))

sns.barplot(
    data=df,
    x='backend',
    y='score',
    hue='n_qubits',
    order=backend_order,  # Ensures x-axis consistency
    palette=custom_palette,
    ax=ax2,
    edgecolor='gray',
    capsize=.1,
    errwidth=1.5 
)

ax2.set_title("QAOA Method: FSWAP", fontsize=15, fontweight='bold', pad=20)
ax2.set_xlabel("Backend", fontsize=12)
ax2.set_ylabel("Score", fontsize=12)
ax2.set_ylim(0, 1.05)
ax2.legend(title="Qubits", loc='upper right')
ax2.axhline(0, color='black', linewidth=0.8)

plt.tight_layout()
plt.savefig("fswap_bar_charts.png", dpi=300)
print("Saved: fswap_bar_charts.png")

plt.show()
